"""One-off, source-checked 2026-09-25 10:00 edition. No credentials in this file."""
import argparse
import datetime as dt
import html
import json
from pathlib import Path
import sys
import time
import daily as d

EDITION_DATE = dt.date(2026, 9, 25)
RECEIPT = 'deliveries/2026-09-25-revision-1000.json'
COLORS = {'A': 'blue', 'B': 'green', 'C': 'orange'}


def card(report):
    elements = [{'tag': 'div', 'text': {'tag': 'lark_md', 'content': '**今日三件事**\n' + '\n'.join(f"{i}. {d.md(t['text'])}" for i,t in enumerate(report['three_things'],1))}},
                {'tag': 'note', 'elements': [{'tag': 'plain_text', 'content': '10:00 专题修订版 · A/B/C 各2篇\n本次按 DOI 复核6篇摘要；所选均为较早文献，不冒充昨日新论文。'}]}, {'tag': 'hr'}]
    for group in 'ABC':
        elements.append({'tag': 'div', 'text': {'tag': 'lark_md', 'content': f'<font color="{COLORS[group]}">**{group} · {d.LABELS[group]}**</font>'}})
        for p in [p for p in report['papers'] if p['group']==group]:
            elements.append({'tag': 'div', 'text': {'tag': 'lark_md', 'content': '**'+d.md(p['title_zh'])+'**\n'+d.md(p['title'],500)}})
            elements.append({'tag': 'note', 'elements': [{'tag': 'plain_text', 'content': '作者：'+' / '.join(p['authors'])+'\n期刊：'+p['journal']+'\n发表：'+p['date']+' · 较早文献补充'}]})
            r=p['review']
            elements.append({'tag': 'div', 'text': {'tag': 'lark_md', 'content': d.md(r['summary'],500)+'\n\n**与你的研究**\n'+d.md(r['why'],400)+'\n**阅读时核查**\n'+d.md(r['next'],300)+f"\n[打开论文 ↗]({p['url']})"}})
        elements.append({'tag':'hr'})
    elements.append({'tag':'note','elements':[{'tag':'plain_text','content':'依据出版方存入 Crossref 的元数据与摘要整理，未阅读全文。研究关联属于编辑判断，不是论文直接证明。作者按来源顺序列出，不推断通讯作者。'}]})
    payload={'msg_type':'interactive','card':{'config':{'wide_screen_mode':True},'header':{'template':'turquoise','title':{'tag':'plain_text','content':'🔬 CK科研日报 · 09.25 · 10:00正式修订版'}},'elements':elements}}
    if len(json.dumps(payload,ensure_ascii=False).encode())>19000:
        raise d.SafeError('CARD_TOO_LARGE')
    return payload


def preview(report, out):
    out.mkdir(parents=True,exist_ok=True)
    payload=card(report)
    (out/'feishu-card.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),'utf-8')
    (out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),'utf-8')
    esc=html.escape
    body='<header><small>CK RESEARCH DAILY / 25 SEP 2026</small><h1>今天，关注机制与证据</h1><p>10:00 正式修订版 · 6 篇研究精选</p></header><section><h2>今日三件事</h2>'
    body+=''.join('<p><b>'+str(i)+'</b> '+esc(t['text'])+'</p>' for i,t in enumerate(report['three_things'],1))+'</section>'
    body+='<p class="meta">专题修订：本次复核 6 篇摘要，均为较早文献补充；非昨日全量扫描。</p>'
    for g in 'ABC':
        body+=f'<h2 class="group {g}">{g} · {esc(d.LABELS[g])}</h2>'
        for p in [p for p in report['papers'] if p['group']==g]:
            body+='<article><h2>'+esc(p['title_zh'])+'</h2><p class="original">'+esc(p['title'])+'</p><div class="meta">作者：'+esc(' / '.join(p['authors']))+'<br>期刊：'+esc(p['journal'])+'<br>发表：'+p['date']+' · 较早文献补充</div>'
            body+='<p>'+esc(p['review']['summary'])+'</p><h3>与你的研究</h3><p>'+esc(p['review']['why'])+'</p><h3>阅读时核查</h3><p>'+esc(p['review']['next'])+'</p><a href="'+esc(p['url'],quote=True)+'">打开论文 ↗</a></article>'
    body+='<footer>依据出版方元数据及摘要整理，未阅读全文。研究关联为编辑判断。<br>此网页是排版预览，飞书客户端的字体、颜色与换行可能不同。</footer>'
    style='body{margin:0 auto;max-width:780px;background:#f4f6f5;color:#183334;font:17px/1.8 system-ui;padding:24px}header{background:#125e62;color:white;border-radius:20px;padding:30px}h1{font-size:30px;line-height:1.35}h2{font-size:22px;line-height:1.5}h3{font-size:16px;margin-bottom:0}section,article{background:white;padding:25px;margin:20px 0;border-radius:16px}.meta,footer{color:#647575;font-size:14px}.meta{background:#f0f5f4;padding:14px;border-radius:8px}.original{font-size:15px;color:#506367}.group{padding-left:15px;border-left:5px solid}.A{color:#2866ab}.B{color:#2d7850}.C{color:#b56824}a{color:#0d7779;font-weight:600}footer{padding:25px}small{letter-spacing:1.5px}'
    (out/'daily.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CK科研日报 · 10:00修订版</title><style>'+style+'</style>'+body+'</html>','utf-8')
    return payload


def deliver(report, state, now=None):
    now=now or dt.datetime.now(d.TZ)
    if now.date()!=EDITION_DATE or now.hour<10:
        raise d.SafeError('REVISION_ONLY_ON_2026_09_25_AFTER_1000_SHANGHAI')
    if not state.read('activation.json'):
        raise d.SafeError('TEST_ACTIVATION_REQUIRED')
    prior=state.read(RECEIPT)
    if prior:
        if prior.get('status')=='sent':
            print('Revision already sent; skipped.')
            return
        raise d.SafeError('DELIVERY_UNCERTAIN_CHECK_GROUP_BEFORE_RETRY')
    d.credentials()
    payload=card(report)
    state.write(RECEIPT,{'status':'pending','edition':'revision-1000'})
    d.send(payload)
    state.write(RECEIPT,{'status':'sent','edition':'revision-1000','ids':[p['id'] for p in report['papers']]})
    history=state.read('history.json') or {'ids':[]}
    state.write('history.json',{'ids':sorted(set(history['ids'])|{p['id'] for p in report['papers']})})
    print('Feishu accepted the formal revision.')


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--send',action='store_true')
    parser.add_argument('--out',type=Path,default=Path('work/ck-daily-output'))
    args=parser.parse_args()
    preview(REPORT,args.out)
    if not args.send:
        print('Revision preview ready; nothing sent.')
        return
    # A manual dispatch at any time today can safely queue the edition until 10:00.
    if dt.datetime.now(d.TZ).date()!=EDITION_DATE:
        raise d.SafeError('REVISION_DATE_EXPIRED')
    d.credentials()
    target=dt.datetime.combine(EDITION_DATE,dt.time(10),d.TZ)
    while dt.datetime.now(d.TZ)<target:
        time.sleep(min(30,(target-dt.datetime.now(d.TZ)).total_seconds()))
    deliver(REPORT,d.State())


